--- LinkRepository.cs ---
using System.Globalization;
using Microsoft.Data.Sqlite;

namespace Service;

/// <summary>
/// The only component that opens a <see cref="SqliteConnection"/> or writes SQL. Owns the
/// insert-with-collision-retry algorithm, the atomic redirect-with-increment statement, and the
/// stats query. See ADR 0001 for why correctness here rests on SQLite's own locking and unique
/// index rather than application-level coordination.
/// </summary>
public sealed class LinkRepository
{
    private const int MaxGeneratedCodeAttempts = 5;
    private const int SqliteConstraintViolation = 19;

    private readonly string _connectionString;

    public LinkRepository(string connectionString)
    {
        _connectionString = connectionString;
    }

    public async Task<RepositoryCreateResult> CreateAsync(string url, string? alias, DateTimeOffset? expiresAt)
    {
        DateTimeOffset createdAt = DateTimeOffset.UtcNow;
        using var connection = new SqliteConnection(_connectionString);
        await connection.OpenAsync();

        if (alias is not null)
        {
            try
            {
                using SqliteCommand insert = connection.CreateCommand();
                insert.CommandText = """
                    INSERT INTO links(code, original_url, created_at, expires_at, click_count)
                    VALUES ($code, $url, $createdAt, $expiresAt, 0);
                    """;
                insert.Parameters.AddWithValue("$code", alias);
                insert.Parameters.AddWithValue("$url", url);
                insert.Parameters.AddWithValue("$createdAt", ToStorageString(createdAt));
                insert.Parameters.AddWithValue("$expiresAt", (object?)ToStorageString(expiresAt) ?? DBNull.Value);
                await insert.ExecuteNonQueryAsync();
                return new RepositoryCreateResult(alias, true);
            }
            catch (SqliteException ex) when (ex.SqliteErrorCode == SqliteConstraintViolation)
            {
                return new RepositoryCreateResult(null, false);
            }
        }

        for (int attempt = 0; attempt < MaxGeneratedCodeAttempts; attempt++)
        {
            long id;
            using (SqliteCommand insert = connection.CreateCommand())
            {
                insert.CommandText = """
                    INSERT INTO links(code, original_url, created_at, expires_at, click_count)
                    VALUES (NULL, $url, $createdAt, $expiresAt, 0);
                    SELECT last_insert_rowid();
                    """;
                insert.Parameters.AddWithValue("$url", url);
                insert.Parameters.AddWithValue("$createdAt", ToStorageString(createdAt));
                insert.Parameters.AddWithValue("$expiresAt", (object?)ToStorageString(expiresAt) ?? DBNull.Value);
                object? scalar = await insert.ExecuteScalarAsync();
                id = Convert.ToInt64(scalar, CultureInfo.InvariantCulture);
            }

            string code = CodeGenerator.Encode(id);
            try
            {
                using SqliteCommand update = connection.CreateCommand();
                update.CommandText = "UPDATE links SET code = $code WHERE id = $id;";
                update.Parameters.AddWithValue("$code", code);
                update.Parameters.AddWithValue("$id", id);
                await update.ExecuteNonQueryAsync();
                return new RepositoryCreateResult(code, true);
            }
            catch (SqliteException ex) when (ex.SqliteErrorCode == SqliteConstraintViolation)
            {
                // The generated code collided with a pre-existing alias. The row with the NULL
                // code stays behind (inert: no query ever matches code IS NULL); retry with a
                // fresh, higher id.
            }
        }

        throw new InvalidOperationException("Failed to generate a unique code after repeated attempts.");
    }

    public async Task<RedirectResult> RedirectAsync(string code)
    {
        DateTimeOffset now = DateTimeOffset.UtcNow;
        using var connection = new SqliteConnection(_connectionString);
        await connection.OpenAsync();

        using (SqliteCommand update = connection.CreateCommand())
        {
            update.CommandText = """
                UPDATE links
                SET click_count = click_count + 1
                WHERE code = $code AND (expires_at IS NULL OR expires_at > $now)
                RETURNING original_url;
                """;
            update.Parameters.AddWithValue("$code", code);
            update.Parameters.AddWithValue("$now", ToStorageString(now));
            using SqliteDataReader reader = await update.ExecuteReaderAsync();
            if (await reader.ReadAsync())
            {
                return RedirectResult.Redirect(reader.GetString(0));
            }
        }

        using SqliteCommand select = connection.CreateCommand();
        select.CommandText = "SELECT 1 FROM links WHERE code = $code;";
        select.Parameters.AddWithValue("$code", code);
        object? exists = await select.ExecuteScalarAsync();
        return exists is null ? RedirectResult.NotFound() : RedirectResult.Expired();
    }

    public async Task<LinkStats?> GetStatsAsync(string code)
    {
        using var connection = new SqliteConnection(_connectionString);
        await connection.OpenAsync();

        using SqliteCommand select = connection.CreateCommand();
        select.CommandText = """
            SELECT code, original_url, created_at, expires_at, click_count
            FROM links WHERE code = $code;
            """;
        select.Parameters.AddWithValue("$code", code);

        using SqliteDataReader reader = await select.ExecuteReaderAsync();
        if (!await reader.ReadAsync())
        {
            return null;
        }

        string resolvedCode = reader.GetString(0);
        string url = reader.GetString(1);
        DateTimeOffset createdAt = ParseStorageString(reader.GetString(2))!.Value;
        DateTimeOffset? expiresAt = reader.IsDBNull(3) ? null : ParseStorageString(reader.GetString(3));
        long clickCount = reader.GetInt64(4);

        return new LinkStats(resolvedCode, url, createdAt, expiresAt, clickCount);
    }

    private static string? ToStorageString(DateTimeOffset? value) =>
        value is null ? null : value.Value.UtcDateTime.ToString("o", CultureInfo.InvariantCulture);

    private static string ToStorageString(DateTimeOffset value) =>
        value.UtcDateTime.ToString("o", CultureInfo.InvariantCulture);

    private static DateTimeOffset? ParseStorageString(string? value) =>
        value is null
            ? null
            : DateTimeOffset.Parse(value, CultureInfo.InvariantCulture, DateTimeStyles.AssumeUniversal | DateTimeStyles.AdjustToUniversal);
}

--- LinkService.cs ---
using System.Globalization;
using System.Text.RegularExpressions;

namespace Service;

/// <summary>
/// Application logic: validates a create request, delegates to <see cref="LinkRepository"/> for
/// persistence, and maps repository results onto the outcomes the HTTP layer understands.
/// </summary>
public sealed partial class LinkService
{
    private readonly LinkRepository _repository;
    private readonly string _baseUrl;

    public LinkService(LinkRepository repository, string baseUrl)
    {
        _repository = repository;
        _baseUrl = baseUrl.EndsWith('/') ? baseUrl : baseUrl + "/";
    }

    public async Task<CreateOutcome> CreateAsync(CreateLinkRequest request)
    {
        if (!UrlValidator.TryValidate(request.Url, out _, out string? urlError))
        {
            return CreateOutcome.Invalid(urlError!);
        }

        if (request.Alias is not null && !AliasPattern().IsMatch(request.Alias))
        {
            return CreateOutcome.Invalid("alias must match ^[A-Za-z0-9]{1,32}$");
        }

        DateTimeOffset? expiresAt = null;
        if (request.ExpiresAt is not null)
        {
            bool hasUtcDesignator = request.ExpiresAt.EndsWith('Z') || request.ExpiresAt.EndsWith("+00:00", StringComparison.Ordinal);
            if (!hasUtcDesignator ||
                !DateTimeOffset.TryParse(
                    request.ExpiresAt,
                    CultureInfo.InvariantCulture,
                    DateTimeStyles.AssumeUniversal | DateTimeStyles.AdjustToUniversal,
                    out DateTimeOffset parsed))
            {
                return CreateOutcome.Invalid("expiresAt must be a valid ISO-8601 UTC timestamp");
            }

            expiresAt = parsed;
        }

        RepositoryCreateResult result = await _repository.CreateAsync(request.Url!, request.Alias, expiresAt);
        if (!result.Success)
        {
            return CreateOutcome.AliasTaken();
        }

        string shortUrl = _baseUrl + result.Code;
        return CreateOutcome.Created(result.Code!, shortUrl);
    }

    public Task<RedirectResult> RedirectAsync(string code) => _repository.RedirectAsync(code);

    public Task<LinkStats?> GetStatsAsync(string code) => _repository.GetStatsAsync(code);

    [GeneratedRegex("^[A-Za-z0-9]{1,32}$")]
    private static partial Regex AliasPattern();
}

--- Models.cs ---
namespace Service;

/// <summary>Request body for POST /api/v1/links.</summary>
public sealed record CreateLinkRequest(string? Url, string? Alias, string? ExpiresAt);

/// <summary>Response body for a successful link creation.</summary>
public sealed record CreateLinkResponse(string Code, string ShortUrl);

/// <summary>Response body returned for link statistics.</summary>
public sealed record LinkStats(string Code, string Url, DateTimeOffset CreatedAt, DateTimeOffset? ExpiresAt, long ClickCount);

/// <summary>Standard error envelope used across all endpoints.</summary>
public sealed record ErrorResponse(string Error, string Message);

/// <summary>Discriminates the outcome of a link-creation attempt.</summary>
public enum CreateOutcomeKind
{
    Created,
    Invalid,
    AliasTaken,
}

/// <summary>Result of attempting to create a link, at the service layer.</summary>
public sealed class CreateOutcome
{
    public CreateOutcomeKind Kind { get; }
    public string? Code { get; }
    public string? ShortUrl { get; }
    public string? Error { get; }

    private CreateOutcome(CreateOutcomeKind kind, string? code, string? shortUrl, string? error)
    {
        Kind = kind;
        Code = code;
        ShortUrl = shortUrl;
        Error = error;
    }

    public static CreateOutcome Created(string code, string shortUrl) => new(CreateOutcomeKind.Created, code, shortUrl, null);
    public static CreateOutcome Invalid(string error) => new(CreateOutcomeKind.Invalid, null, null, error);
    public static CreateOutcome AliasTaken() => new(CreateOutcomeKind.AliasTaken, null, null, null);
}

/// <summary>Discriminates the outcome of a redirect attempt.</summary>
public enum RedirectKind
{
    Redirect,
    NotFound,
    Expired,
}

/// <summary>Result of attempting to redirect a short code, at the repository/service layer.</summary>
public sealed class RedirectResult
{
    public RedirectKind Kind { get; }
    public string? Url { get; }

    private RedirectResult(RedirectKind kind, string? url)
    {
        Kind = kind;
        Url = url;
    }

    public static RedirectResult Redirect(string url) => new(RedirectKind.Redirect, url);
    public static RedirectResult NotFound() => new(RedirectKind.NotFound, null);
    public static RedirectResult Expired() => new(RedirectKind.Expired, null);
}

/// <summary>Result of the repository's create operation, before the service layer maps it to a <see cref="CreateOutcome"/>.</summary>
public sealed record RepositoryCreateResult(string? Code, bool Success);

--- Program.cs ---
using Microsoft.AspNetCore.Http.Json;
using Service;
using System.Text.Json;

WebApplicationBuilder builder = WebApplication.CreateBuilder(args);

builder.Services.ConfigureHttpJsonOptions(options =>
{
    options.SerializerOptions.PropertyNamingPolicy = JsonNamingPolicy.CamelCase;
});

string connectionString = builder.Configuration.GetConnectionString("Sqlite") ?? "Data Source=links.db";
string baseUrl = builder.Configuration["BaseUrl"] ?? "http://localhost:5000/";

SchemaInitializer.Initialize(connectionString);

builder.Services.AddSingleton(new LinkRepository(connectionString));
builder.Services.AddSingleton(sp => new LinkService(sp.GetRequiredService<LinkRepository>(), baseUrl));

WebApplication app = builder.Build();

app.MapGet("/health/live", () => Results.Ok(HealthStatus.Live));

app.MapPost("/api/v1/links", async (CreateLinkRequest request, LinkService service) =>
{
    CreateOutcome outcome = await service.CreateAsync(request);
    return outcome.Kind switch
    {
        CreateOutcomeKind.Invalid => Results.Json(new ErrorResponse("invalid_request", outcome.Error!), statusCode: StatusCodes.Status400BadRequest),
        CreateOutcomeKind.AliasTaken => Results.Json(new ErrorResponse("alias_taken", "The requested alias is already taken."), statusCode: StatusCodes.Status409Conflict),
        CreateOutcomeKind.Created => Results.Json(new CreateLinkResponse(outcome.Code!, outcome.ShortUrl!), statusCode: StatusCodes.Status201Created),
        _ => Results.Problem(),
    };
});

app.MapGet("/api/v1/links/{code}/stats", async (string code, LinkService service) =>
{
    LinkStats? stats = await service.GetStatsAsync(code);
    if (stats is null)
    {
        return Results.Json(new ErrorResponse("not_found", "No link exists for this code."), statusCode: StatusCodes.Status404NotFound);
    }

    return Results.Json(stats, statusCode: StatusCodes.Status200OK);
});

app.MapGet("/{code}", async (string code, LinkService service) =>
{
    RedirectResult result = await service.RedirectAsync(code);
    return result.Kind switch
    {
        RedirectKind.Redirect => Results.Redirect(result.Url!, permanent: false),
        RedirectKind.NotFound => Results.Json(new ErrorResponse("not_found", "No link exists for this code."), statusCode: StatusCodes.Status404NotFound),
        RedirectKind.Expired => Results.Json(new ErrorResponse("expired", "The link has expired."), statusCode: StatusCodes.Status410Gone),
        _ => Results.Problem(),
    };
});

app.Run();

/// <summary>What the liveness endpoint reports.</summary>
public sealed record HealthStatus(string Status)
{
    /// <summary>The service is up.</summary>
    public static HealthStatus Live { get; } = new("live");
}

--- README.md ---
# Service skeleton

The starting tree for a run's workspace: a minimal, buildable .NET project that an
implementation stage extends.

It exists so that compensation can be demonstrated against a real version-controlled tree
rather than against throwaway files — a `git revert` that restores an actual project is
evidence; one that restores a scratch file is a formality.

Greenfield runs grow the URL shortener from here.


--- SchemaInitializer.cs ---
using Microsoft.Data.Sqlite;

namespace Service;

/// <summary>Creates the schema if absent and sets the pragmas that make concurrent access safe.</summary>
public static class SchemaInitializer
{
    public static void Initialize(string connectionString)
    {
        using var connection = new SqliteConnection(connectionString);
        connection.Open();

        using (SqliteCommand pragmaCommand = connection.CreateCommand())
        {
            pragmaCommand.CommandText = "PRAGMA journal_mode=WAL; PRAGMA busy_timeout=5000;";
            pragmaCommand.ExecuteNonQuery();
        }

        using SqliteCommand createCommand = connection.CreateCommand();
        createCommand.CommandText = """
            CREATE TABLE IF NOT EXISTS links (
                id            INTEGER PRIMARY KEY AUTOINCREMENT,
                code          TEXT UNIQUE,
                original_url  TEXT NOT NULL,
                created_at    TEXT NOT NULL,
                expires_at    TEXT,
                click_count   INTEGER NOT NULL DEFAULT 0
            );
            """;
        createCommand.ExecuteNonQuery();
    }
}

--- Service.csproj ---
<Project Sdk="Microsoft.NET.Sdk.Web">

  <!-- Target framework, language version and nullability: Directory.Build.props -->

  <PropertyGroup>
    <RootNamespace>Service</RootNamespace>
  </PropertyGroup>

  <ItemGroup>
    <!-- The store the lifecycle's requirements call for, referenced up front so an
         implementation stage never has to edit a project file to get one. -->
    <PackageReference Include="Microsoft.Data.Sqlite" />
  </ItemGroup>

  <ItemGroup>
    <!--
      The test project lives under this one's directory, so the SDK's default glob would
      compile its files into the service. Excluded rather than moved: keeping the service at
      the tree root means every .cs file an implementation stage writes, wherever it puts it,
      is part of the build — and therefore part of what the build gate actually checks. Under
      a src/Service/ layout, a file written one directory off would compile nowhere, pass the
      gate, and ship as inert code nobody noticed.
    -->
    <Compile Remove="tests/**" />
    <Content Remove="tests/**" />
    <None Remove="tests/**" />
  </ItemGroup>

</Project>


--- UrlValidator.cs ---
using System.Net;
using System.Net.Sockets;

namespace Service;

/// <summary>
/// Pure validation of candidate URLs: scheme allow-list and literal-IP private/loopback/
/// link-local range checks. Never performs DNS resolution — only literal IP hosts are checked
/// against ranges, per requirement.
/// </summary>
public static class UrlValidator
{
    private static readonly (IPAddress Network, int Prefix)[] BlockedV4 =
    {
        (IPAddress.Parse("127.0.0.0"), 8),   // loopback
        (IPAddress.Parse("169.254.0.0"), 16), // link-local
        (IPAddress.Parse("10.0.0.0"), 8),     // RFC 1918
        (IPAddress.Parse("172.16.0.0"), 12),  // RFC 1918
        (IPAddress.Parse("192.168.0.0"), 16), // RFC 1918
    };

    private static readonly (IPAddress Network, int Prefix)[] BlockedV6 =
    {
        (IPAddress.Parse("::1"), 128),   // loopback
        (IPAddress.Parse("fe80::"), 10), // link-local
        (IPAddress.Parse("fc00::"), 7),  // unique-local
    };

    /// <summary>Validates a candidate URL. On success, <paramref name="uri"/> holds the parsed URI.</summary>
    public static bool TryValidate(string? url, out Uri? uri, out string? error)
    {
        uri = null;
        error = null;

        if (string.IsNullOrWhiteSpace(url))
        {
            error = "url is required";
            return false;
        }

        if (!Uri.TryCreate(url, UriKind.Absolute, out Uri? parsed))
        {
            error = "url must be an absolute URI";
            return false;
        }

        if (!string.Equals(parsed.Scheme, "http", StringComparison.OrdinalIgnoreCase) &&
            !string.Equals(parsed.Scheme, "https", StringComparison.OrdinalIgnoreCase))
        {
            error = "url scheme must be http or https";
            return false;
        }

        UriHostNameType hostType = Uri.CheckHostName(parsed.Host);
        if ((hostType == UriHostNameType.IPv4 || hostType == UriHostNameType.IPv6) &&
            IPAddress.TryParse(parsed.Host, out IPAddress? ip) &&
            IsBlocked(ip))
        {
            error = "url host is not permitted";
            return false;
        }

        uri = parsed;
        return true;
    }

    private static bool IsBlocked(IPAddress ip)
    {
        (IPAddress Network, int Prefix)[] ranges = ip.AddressFamily == AddressFamily.InterNetwork ? BlockedV4 : BlockedV6;
        foreach ((IPAddress network, int prefix) in ranges)
        {
            if (IsInRange(ip, network, prefix))
            {
                return true;
            }
        }

        return false;
    }

    private static bool IsInRange(IPAddress address, IPAddress network, int prefixLength)
    {
        if (address.AddressFamily != network.AddressFamily)
        {
            return false;
        }

        byte[] addressBytes = address.GetAddressBytes();
        byte[] networkBytes = network.GetAddressBytes();
        int fullBytes = prefixLength / 8;
        int remainingBits = prefixLength % 8;

        for (int i = 0; i < fullBytes; i++)
        {
            if (addressBytes[i] != networkBytes[i])
            {
                return false;
            }
        }

        if (remainingBits > 0)
        {
            int mask = (byte)(0xFF << (8 - remainingBits));
            if ((addressBytes[fullBytes] & mask) != (networkBytes[fullBytes] & mask))
            {
                return false;
            }
        }

        return true;
    }
}

