--- contracts/openapi.yaml ---
openapi: 3.1.0
info:
  title: URL Shortener Service
  version: "1.0.0"
  description: >
    Creates short links, redirects short codes to their original URLs while tracking clicks,
    and reports per-link statistics. Backed by SQLite; no authentication.
servers:
  - url: /
paths:
  /api/v1/links:
    post:
      operationId: createLink
      summary: Create a short link
      requestBody:
        required: true
        content:
          application/json:
            schema:
              $ref: '#/components/schemas/CreateLinkRequest'
      responses:
        '201':
          description: Link created
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/CreateLinkResponse'
        '400':
          description: >
            Invalid request: `url` missing, `url` scheme not http/https, `url` host is a
            loopback/link-local/RFC1918/IPv6-private-equivalent IP literal, `alias` malformed,
            or `expiresAt` not valid ISO-8601 UTC.
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/Error'
        '409':
          description: The requested alias is already taken. No link was created.
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/Error'
  /{code}:
    get:
      operationId: redirectToOriginalUrl
      summary: Redirect to the original URL and record a click
      parameters:
        - name: code
          in: path
          required: true
          schema:
            type: string
            pattern: '^[A-Za-z0-9]{1,32}$'
      responses:
        '302':
          description: Redirect to the original URL. The link's click count was incremented by 1.
          headers:
            Location:
              description: The original URL.
              schema:
                type: string
                format: uri
        '404':
