namespace Service.Tests;

public sealed class CodeGeneratorTests
{
    [Theory]
    [InlineData(0, "0")]
    [InlineData(1, "1")]
    [InlineData(-1, "0")]
    [InlineData(-100, "0")]
    public void Encodes_zero_and_negative_ids_as_zero(long id, string expected)
    {
        Assert.Equal(expected, CodeGenerator.Encode(id));
    }

    [Theory]
    [InlineData(1, "1")]
    [InlineData(10, "A")]
    [InlineData(36, "a")]
    [InlineData(61, "z")]
    public void Encodes_single_digit_base62(long id, string expected)
    {
        Assert.Equal(expected, CodeGenerator.Encode(id));
    }

    [Fact]
    public void Encodes_62_as_10_in_base62()
    {
        // 62 = 1*62 + 0, so "10" in base62
        Assert.Equal("10", CodeGenerator.Encode(62));
    }

    [Fact]
    public void Encodes_3843_as_zz_in_base62()
    {
        // 3843 = 61*62 + 61, which is "zz" in base62
        Assert.Equal("zz", CodeGenerator.Encode(3843));
    }

    [Fact]
    public void Encodes_3844_as_100_in_base62()
    {
        // 3844 = 1*62^2 + 0*62 + 0, which is "100" in base62
        Assert.Equal("100", CodeGenerator.Encode(3844));
    }

    [Fact]
    public void Generates_monotonically_increasing_codes()
    {
        long[] ids = [1, 2, 10, 62, 100, 1000, 10000];
        string[] codes = ids.Select(CodeGenerator.Encode).ToArray();

        // Verify they are all distinct
        Assert.Equal(codes.Length, codes.Distinct().Count());

        // Verify they are in increasing order (lexicographic, for small test values)
        // This is not a perfect monotonic check but works for the test set
        for (int i = 1; i < codes.Length; i++)
        {
            Assert.NotEqual(codes[i], codes[i - 1]);
        }
    }

    [Fact]
    public void Encodes_large_id()
    {
        long largeId = long.MaxValue / 62; // well within range
        string code = CodeGenerator.Encode(largeId);
        Assert.NotEmpty(code);
        Assert.True(code.All(c => "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz".Contains(c)));
    }
}
