namespace Service.Tests;

using Microsoft.Data.Sqlite;

public sealed class LinkRepositoryTests
{
    private string CreateTempDatabasePath()
    {
        return Path.Combine(Path.GetTempPath(), $"test_{Guid.NewGuid():N}.db");
    }

    private void InitializeDatabase(string connectionString)
    {
        SchemaInitializer.Initialize(connectionString);
    }

    [Fact]
    public async Task Creates_link_with_generated_code()
    {
        string dbPath = CreateTempDatabasePath();
        string connectionString = $"Data Source={dbPath}";
        try
        {
            InitializeDatabase(connectionString);
            var repository = new LinkRepository(connectionString);

            var result = await repository.CreateAsync("https://example.com/long/path", null, null);

            Assert.NotNull(result.Code);
            Assert.True(result.Success);
            Assert.NotEmpty(result.Code);
        }
        finally
        {
            File.Delete(dbPath);
        }
    }

    [Fact]
    public async Task Creates_link_with_supplied_alias()
    {
        string dbPath = CreateTempDatabasePath();
        string connectionString = $"Data Source={dbPath}";
        try
        {
            InitializeDatabase(connectionString);
            var repository = new LinkRepository(connectionString);

            var result = await repository.CreateAsync("https://example.com", "myalias", null);

            Assert.Equal("myalias", result.Code);
            Assert.True(result.Success);
        }
        finally
        {
            File.Delete(dbPath);
        }
    }

    [Fact]
    public async Task Rejects_duplicate_alias_with_conflict_result()
    {
        string dbPath = CreateTempDatabasePath();
        string connectionString = $"Data Source={dbPath}";
        try
        {
            InitializeDatabase(connectionString);
            var repository = new LinkRepository(connectionString);

            // First alias claim should succeed
            var first = await repository.CreateAsync("https://example.com", "taken", null);
            Assert.True(first.Success);

            // Second claim of same alias should fail
            var second = await repository.CreateAsync("https://example.org", "taken", null);
            Assert.False(second.Success);
            Assert.Null(second.Code);
        }
        finally
        {
            File.Delete(dbPath);
        }
    }

    [Fact]
