            var result = await repository.CreateAsync("https://example.com", "expiring", expiresAt);
            Assert.True(result.Success);

            var stats = await repository.GetStatsAsync("expiring");
            Assert.NotNull(stats);
            Assert.NotNull(stats.ExpiresAt);
            // Allow small rounding differences in storage/retrieval
            Assert.True((stats.ExpiresAt.Value - expiresAt).Duration() < TimeSpan.FromSeconds(1));
        }
        finally
